insert into learning_mod.quizzes (
    reading_id,
    question,
    option_a,
    option_b,
    option_c,
    option_d,
    correct_answer,
    explanation,
    difficulty,
    points,
    created_at
)
select
    r.id,
    q.question,
    q.option_a,
    q.option_b,
    q.option_c,
    q.option_d,
    q.correct_answer,
    q.explanation,
    q.difficulty,
    q.points,
    now()
from quiz_seed q
join learning_mod.readings r on lower(r.title) = lower(q.reading_title)
where not exists (
    select 1
    from learning_mod.quizzes existing
    where existing.reading_id = r.id
      and lower(existing.question) = lower(q.question)
);

commit;
